mapper.select:
SELECT LOG_ID, ACTION, TARGET_TYPE, TARGET_ID, DETAIL, WORKER, WORK_IP, WORK_DT
  FROM SM_AUDIT_LOG


        AND TARGET_TYPE = #{targetType}


        AND TARGET_ID = #{targetId}


        AND WORKER = #{worker}


 ORDER BY WORK_DT DESC, LOG_ID DESC


        FETCH FIRST #{limit} ROWS ONLY


        LIMIT #{limit}
